// Generated by sel-pull (Shared Element Library): do not edit, it is replaced by the next "sel-pull firebase".
//
// npm run dev:pull: copies the LIVE Firestore database and the Auth accounts into the local emulators, to reproduce something with real
// data. Signing in as any of those people locally shows exactly what they see (their uid is kept, so data keyed by uid still matches).
//
// Read-only on production: this process only lists and reads (no write call exists in this file), saves everything to
// .emulator/live-copy.json (git-ignored: it is production data, keep it on this machine), and then hands that file to load.mjs, which runs
// in its own process pointed at the emulators. npm run dev:load reloads the saved copy later without reading production again.
//
// Needs your own Google login once (no key file): gcloud auth application-default login
import fs from "node:fs";
import http from "node:http";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const PROJECT_ID = JSON.parse(fs.readFileSync(path.join(ROOT, ".firebaserc"), "utf8")).projects.default;
const OUT = path.join(ROOT, ".emulator", "live-copy.json");
const PENDING = path.join(ROOT, ".emulator", "load-on-start"); // the next npm run dev loads the copy (see start.mjs)

for (const name of ["FIRESTORE_EMULATOR_HOST", "FIREBASE_AUTH_EMULATOR_HOST"]) {
  if (process.env[name]) {
    console.error(`${name} is set, so this would read the emulator instead of the live project. Unset it and run again.`);
    process.exit(1);
  }
}
process.env.METADATA_SERVER_DETECTION = "none"; // not on a Google Cloud machine: your own login is the credential

const { initializeApp, applicationDefault } = await import("firebase-admin/app");
const { getFirestore, Timestamp, GeoPoint } = await import("firebase-admin/firestore");
const { getAuth } = await import("firebase-admin/auth");
const credential = applicationDefault();
try {
  await credential.getAccessToken();
} catch {
  console.error("No Google login for scripts on this machine yet. Run this once, then try again:\n  gcloud auth application-default login");
  process.exit(1);
}
const app = initializeApp({ credential, projectId: PROJECT_ID }, "live");
const db = getFirestore(app);

// The tagging decode() in emulator.mjs reads back (repeated here so this process never loads the emulator module; keep the two in step).
// FORMAT 2: every special value is an object with exactly ONE reserved key "$sel"; a map that itself has a "$sel" key is wrapped.
// See emulator.mjs for the list. A copy without "version" is format 1 ("__type" tags) and still loads.
const FORMAT = 2;
function encode(value) {
  if (value instanceof Timestamp) return { $sel: "timestamp", seconds: value.seconds, nanoseconds: value.nanoseconds };
  if (value instanceof GeoPoint) return { $sel: "geopoint", latitude: value.latitude, longitude: value.longitude };
  if (value && typeof value === "object" && typeof value.path === "string" && typeof value.listCollections === "function") return { $sel: "ref", path: value.path };
  if (Buffer.isBuffer(value) || value instanceof Uint8Array) return { $sel: "bytes", base64: Buffer.from(value).toString("base64") };
  if (typeof value === "number" && !Number.isFinite(value)) return { $sel: "number", value: String(value) };
  if (Array.isArray(value)) return value.map(encode);
  if (value && typeof value === "object") {
    const entries = Object.fromEntries(Object.entries(value).map(([k, v]) => [k, encode(v)]));
    return Object.prototype.hasOwnProperty.call(value, "$sel") ? { $sel: "map", value: entries } : entries;
  }
  return value;
}

const docs = [];
// listDocuments() also returns documents that only hold subcollections (they have no fields of their own, but their children count).
async function readCollection(collection) {
  const refs = await collection.listDocuments();
  for (let i = 0; i < refs.length; i += 100) {
    const snaps = await db.getAll(...refs.slice(i, i + 100));
    for (const snap of snaps) if (snap.exists) docs.push({ path: snap.ref.path, data: encode(snap.data()) });
  }
  for (const ref of refs) for (const sub of await ref.listCollections()) await readCollection(sub);
}

console.log(`Reading the live database of ${PROJECT_ID} (read-only)...`);
try {
  for (const collection of await db.listCollections()) {
    process.stdout.write(`  ${collection.id}...`);
    const before = docs.length;
    await readCollection(collection);
    console.log(` ${docs.length - before} documents`);
  }
} catch (err) {
  console.error(`\nReading the live database failed: ${err.message}`);
  if (/PERMISSION_DENIED|invalid_grant|reauth/i.test(err.message)) console.error(`Your login needs read access to ${PROJECT_ID}; log in again with: gcloud auth application-default login`);
  process.exit(1);
}

// The accounts (no passwords: the emulator's sign-in picker needs none). Optional: without access to Auth, load.mjs makes an account for
// every email address it finds in the data instead.
let accounts = null;
let noEmail = 0;
try {
  accounts = [];
  let pageToken;
  do {
    const page = await getAuth(app).listUsers(1000, pageToken);
    for (const u of page.users) {
      if (!u.email) { noEmail++; continue; }
      const google = u.providerData.find((p) => p.providerId !== "password") || u.providerData[0];
      accounts.push({
        uid: u.uid, email: u.email, displayName: u.displayName || null, photoURL: u.photoURL || null,
        provider: google ? google.providerId : "password", providerUid: google ? google.uid : undefined,
        emailVerified: u.emailVerified === true, disabled: u.disabled === true,
        ...(u.phoneNumber ? { phoneNumber: u.phoneNumber } : {}),
        ...(u.customClaims && Object.keys(u.customClaims).length ? { customClaims: u.customClaims } : {}),
      });
    }
    pageToken = page.pageToken;
  } while (pageToken);
  console.log(`  accounts... ${accounts.length}${noEmail ? ` (${noEmail} without an email address, such as phone or anonymous sign-ins, cannot be copied)` : ""}`);
} catch (err) {
  accounts = null;
  console.log(`  accounts... not readable (${err.message.split("\n")[0]}); accounts will be made from the email addresses in the data`);
}

// Written to a temporary file next to the copy and renamed over it, so an interrupted or failing pull cannot destroy the last good copy.
const tmp = `${OUT}.tmp`;
try {
  fs.mkdirSync(path.dirname(OUT), { recursive: true });
  fs.writeFileSync(tmp, JSON.stringify({ version: FORMAT, project: PROJECT_ID, pulledAt: new Date().toISOString(), docs, accounts }));
  fs.renameSync(tmp, OUT);
} catch (err) {
  try { fs.rmSync(tmp, { force: true }); } catch { /* nothing more to clean up */ }
  console.error(`Saving the copy failed: ${err.message}. The previous copy (if any) is unchanged.`);
  process.exit(1);
}
console.log(`Saved ${docs.length} documents to ${path.relative(ROOT, OUT)}.`);

// Loaded now when the emulators run; otherwise by the next npm run dev (starting them now would bring back the data saved at the last
// stop, and the copy would be lost from sight).
const firestore = (JSON.parse(fs.readFileSync(path.join(ROOT, "firebase.json"), "utf8")).emulators || {}).firestore;
const running = !!firestore && (await new Promise((resolve) => {
  http.get(`http://${firestore.host || "127.0.0.1"}:${firestore.port}/`, { agent: false }, (res) => { res.resume(); resolve(true); }).on("error", () => resolve(false));
}));
if (!running) {
  fs.writeFileSync(PENDING, OUT);
  console.log("The emulators aren't running: the copy is loaded automatically when you start them with npm run dev.");
  process.exit(0);
}
const load = spawnSync(process.execPath, [path.join(ROOT, "scripts/sel-dev/load.mjs"), OUT], { stdio: "inherit" });
process.exit(load.status ?? 1);
